16	    /**
17	     * @return iterable<string, array{array{name: string, files: array<array-key, string>, commands: list<list<string>>}, list<array{exit: int, output: string, files: array<array-key, string>}>}>
18	     */
19	    public function scenarios(): iterable
20	    {
21	        $base = dirname(__DIR__) . '/Fixture/Behavior/';
22	        $source = file_get_contents($base . 'scenarios.json');
23	        $expectedSource = file_get_contents($base . 'expected.json');
24	        if ($source === false || $expectedSource === false) {
25	            throw new RuntimeException('Missing guard characterization fixtures.');
26	        }
27	        /** @var list<array{name: string, files: array<array-key, string>, commands: list<list<string>>}> $scenarios */
28	        $scenarios = json_decode($source, true, 512, JSON_THROW_ON_ERROR);
29	        /** @var array<string, list<array{exit: int, output: string, files: array<array-key, string>}>> $expected */
30	        $expected = json_decode($expectedSource, true, 512, JSON_THROW_ON_ERROR);
31	        $yamlVersion = InstalledVersions::getVersion('symfony/yaml');
32	        $yamlMajor = $yamlVersion === null ? '' : explode('.', $yamlVersion)[0];
33	        $variant = $base . 'expected-yaml' . $yamlMajor . '.json';
34	        if (is_file($variant)) {
35	            $variantSource = file_get_contents($variant);
36	            if ($variantSource === false) {
37	                throw new RuntimeException('Cannot read YAML-version characterization fixture.');
38	            }
39	            /** @var array<string, list<array{exit: int, output: string, files: array<array-key, string>}>> $overrides */
40	            $overrides = json_decode($variantSource, true, 512, JSON_THROW_ON_ERROR);
41	            $expected = array_replace($expected, $overrides);
42	        }
43	        foreach ($scenarios as $scenario) {
44	            yield $scenario['name'] => [$scenario, $expected[$scenario['name']]];
45	        }
46	    }
47	    /**
48	     * @param array{name: string, files: array<array-key, string>, commands: list<list<string>>} $scenario
49	     * @return list<array{exit: int, output: string, files: array<array-key, string>}>
50	     */
51	    public function run(array $scenario): array
52	    {
53	        $package = dirname(__DIR__, 2);
54	        $project = new Project($scenario['files']);
55	        $results = [];
56	        try {
57	            foreach ($scenario['commands'] as $command) {
58	                $output = '';
59	                $application = new Application($project->root, static function (string $text) use (&$output): void {
60	                    $output .= $text;
61	                });
62	                $exit = $application->run($command);
63	                $results[] = ['exit' => $exit, 'output' => str_replace([$project->root, $package], ['<project>', '<package>'], $output), 'files' => $project->files()];
64	            }
65	        } finally {
66	            $project->remove();
67	        }
68	        return $results;
69	    }
70	}
